/**
 * CheckoutInline — Integrated Stripe checkout within the pre-checkout popup style
 * 
 * This page shows the delivery form + Stripe Payment Element together on one page,
 * matching the OrderPopup's branded aesthetic. Uses Stripe's latest features:
 * - Link (saved cards, SMS verification)
 * - All available payment methods from the Stripe account
 * - Express Checkout (Apple Pay, Google Pay)
 * - Browser autofill via proper autocomplete attributes
 * 
 * DEBUG MODE: Only accessible via ?debug=1 URL parameter
 * Route: /checkout-inline?debug=1
 */

import { useState, useCallback, useMemo, useEffect, useRef } from "react";
import { loadStripe } from "@stripe/stripe-js";
import {
  Elements,
  PaymentElement,
  ExpressCheckoutElement,
  useStripe,
  useElements,
} from "@stripe/react-stripe-js";
import { trpc } from "@/lib/trpc";
import type { ShippingAddress } from "@/checkout/types";
import { SUPPORTED_COUNTRIES, US_STATES, CA_PROVINCES, AU_STATES } from "@/checkout/types";
import {
  Lock, Shield, ChevronDown, AlertCircle, Check, Truck, ArrowRight,
  ShieldCheck, Star, Clock, Package, CreditCard, Sparkles,
} from "lucide-react";
import FluffLogo from "@/components/FluffLogo";

/* ─── Constants ─── */
const UNIT_PRICE = 14.97;
const ORIGINAL_UNIT_PRICE = 59.99;
const QUANTITY = 4;
const SUBTOTAL = UNIT_PRICE * QUANTITY;
const ORIGINAL_TOTAL = ORIGINAL_UNIT_PRICE * QUANTITY;
const SAVINGS = ORIGINAL_TOTAL - SUBTOTAL;

/* ─── Debug Gate ─── */
function DebugGate({ children }: { children: React.ReactNode }) {
  const params = new URLSearchParams(window.location.search);
  const isDebug = params.get("debug") === "1";

  if (!isDebug) {
    return (
      <div className="min-h-screen bg-[#FAF3EF] flex items-center justify-center p-6">
        <div className="max-w-md text-center">
          <div className="w-16 h-16 rounded-full bg-amber-100 flex items-center justify-center mx-auto mb-4">
            <Lock className="w-7 h-7 text-amber-600" />
          </div>
          <h1 className="text-xl font-bold text-gray-900 mb-2">Debug Mode Required</h1>
          <p className="text-sm text-gray-600 mb-4">
            This checkout flow is in development. Add <code className="bg-gray-100 px-1.5 py-0.5 rounded text-xs font-mono">?debug=1</code> to the URL to access it.
          </p>
        </div>
      </div>
    );
  }

  return <>{children}</>;
}

/* ─── Payment Form (rendered inside Elements provider) ─── */
function StripePaymentForm({
  onSuccess,
  onError,
  isProcessing,
  setIsProcessing,
  totalAmount,
  email,
}: {
  onSuccess: (id: string) => void;
  onError: (msg: string) => void;
  isProcessing: boolean;
  setIsProcessing: (v: boolean) => void;
  totalAmount: string;
  email: string;
}) {
  const stripe = useStripe();
  const elements = useElements();
  const [paymentReady, setPaymentReady] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [expressAvailable, setExpressAvailable] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!stripe || !elements) return;

    setIsProcessing(true);
    setErrorMessage(null);

    try {
      const { error, paymentIntent } = await stripe.confirmPayment({
        elements,
        confirmParams: {
          return_url: `${window.location.origin}/checkout/confirmation`,
          receipt_email: email,
        },
        redirect: "if_required",
      });

      if (error) {
        const msg =
          error.type === "card_error" || error.type === "validation_error"
            ? error.message || "Payment failed"
            : "An unexpected error occurred. Please try again.";
        setErrorMessage(msg);
        onError(msg);
      } else if (paymentIntent?.status === "succeeded") {
        onSuccess(paymentIntent.id);
      }
    } catch (err: any) {
      const msg = err.message || "Payment processing failed";
      setErrorMessage(msg);
      onError(msg);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleExpressConfirm = async () => {
    if (!stripe || !elements) return;
    setIsProcessing(true);
    try {
      const { error, paymentIntent } = await stripe.confirmPayment({
        elements,
        confirmParams: {
          return_url: `${window.location.origin}/checkout/confirmation`,
        },
        redirect: "if_required",
      });
      if (error) {
        onError(error.message || "Express payment failed");
      } else if (paymentIntent?.status === "succeeded") {
        onSuccess(paymentIntent.id);
      }
    } catch (err: any) {
      onError(err.message || "Express payment failed");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      {/* Express Checkout (Apple Pay, Google Pay) */}
      <div>
        <ExpressCheckoutElement
          onConfirm={handleExpressConfirm}
          onReady={(e) => {
            const available =
              e.availablePaymentMethods != null &&
              Object.values(e.availablePaymentMethods).some(Boolean);
            setExpressAvailable(available);
          }}
          options={{
            buttonType: { applePay: "buy", googlePay: "buy" },
            buttonTheme: { applePay: "black", googlePay: "black" },
            layout: { maxColumns: 2, maxRows: 1 },
          }}
        />
      </div>

      {/* Divider between express and card */}
      {expressAvailable && (
        <div className="flex items-center gap-3 py-1">
          <div className="flex-1 h-px bg-gray-200" />
          <span className="text-[11px] text-gray-500 uppercase tracking-wider font-medium">
            Or pay with card
          </span>
          <div className="flex-1 h-px bg-gray-200" />
        </div>
      )}

      {/* Stripe Payment Element — shows all available methods, Link, saved cards */}
      <PaymentElement
        onReady={() => setPaymentReady(true)}
        options={{
          layout: { type: "tabs" },
          business: { name: "FluffCo" },
          defaultValues: {
            billingDetails: {
              email: email,
            },
          },
        }}
      />

      {/* Error message */}
      {errorMessage && (
        <div className="flex items-start gap-2 p-3 rounded-lg bg-red-50 border border-red-200">
          <AlertCircle className="w-4 h-4 text-red-500 flex-shrink-0 mt-0.5" />
          <p className="text-sm text-red-700">{errorMessage}</p>
        </div>
      )}

      {/* Pay Button */}
      <button
        type="submit"
        disabled={!stripe || !elements || isProcessing || !paymentReady}
        className={`w-full bg-[#e63946] hover:bg-[#d62839] text-white font-semibold py-4 rounded-xl text-base transition-all flex items-center justify-center gap-2 shadow-lg shadow-red-200/30 ${
          isProcessing || !paymentReady
            ? "opacity-70 cursor-wait"
            : "hover:shadow-xl active:scale-[0.99]"
        }`}
      >
        {isProcessing ? (
          <>
            <svg
              className="animate-spin h-4 w-4 text-white"
              xmlns="http://www.w3.org/2000/svg"
              fill="none"
              viewBox="0 0 24 24"
            >
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
              <path
                className="opacity-75"
                fill="currentColor"
                d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
              />
            </svg>
            <span>Processing...</span>
          </>
        ) : (
          <>
            <Lock className="w-4 h-4" />
            <span>Complete Order — {totalAmount}</span>
          </>
        )}
      </button>

      {/* Trust line */}
      <div className="flex items-center justify-center gap-5 pt-1">
        <span className="flex items-center gap-1.5 text-xs text-gray-500">
          <Lock className="w-3.5 h-3.5" />
          256-bit SSL
        </span>
        <span className="flex items-center gap-1.5 text-xs text-gray-500">
          <ShieldCheck className="w-3.5 h-3.5" />
          Safe Checkout
        </span>
        <span className="flex items-center gap-1.5 text-xs text-gray-500">
          <Clock className="w-3.5 h-3.5" />
          30-Night Trial
        </span>
      </div>
    </form>
  );
}

